-- supabase/sql/exam_question_bank_neet_ug_set1.sql
--
-- First curated question-bank batch for 'NEET UG' (see exam_patterns_neet_ug.sql for the exam's
-- structure). Same exam_question_bank table/schema as the other sets -- no migration needed.
--
-- Like NEET PG (and unlike the JEE sets), NEET UG's real format is 100% single-best-response MCQ
-- (4 options, exactly one correct) -- no multi-correct, numerical, or descriptive format in the
-- actual exam. Each of the 16 chapters (4 each across Physics, Chemistry, Botany, Zoology) gets 4
-- classic, high-yield NCERT-based questions.
--
-- Run this once in the Supabase SQL Editor, after exam_patterns_neet_ug.sql.

insert into exam_question_bank (exam_name, subject, chapter, difficulty, format, text, options, numerical_answer, explanation) values

-- Physics: Mechanics
('NEET UG', 'Physics', 'Mechanics', 'easy', 'mcq',
 'The SI unit of impulse is the same as the SI unit of:',
 '[{"text":"Force","isCorrect":false},{"text":"Momentum","isCorrect":true},{"text":"Energy","isCorrect":false},{"text":"Power","isCorrect":false}]'::jsonb,
 null, 'Impulse equals the change in momentum (Impulse = F*t = deltaP), so it shares the same SI unit, kg m/s, as momentum.'),
('NEET UG', 'Physics', 'Mechanics', 'medium', 'mcq',
 'A body moving in a circle at constant speed experiences an acceleration that is:',
 '[{"text":"Zero, since speed is constant","isCorrect":false},{"text":"Constant in magnitude, directed toward the center","isCorrect":true},{"text":"Constant in magnitude, directed away from the center","isCorrect":false},{"text":"Increasing continuously","isCorrect":false}]'::jsonb,
 null, 'Even at constant speed, the direction of velocity keeps changing, producing a centripetal acceleration of constant magnitude v^2/r directed toward the center.'),
('NEET UG', 'Physics', 'Mechanics', 'medium', 'mcq',
 'The work done by the centripetal force on a particle undergoing uniform circular motion is:',
 '[{"text":"Positive","isCorrect":false},{"text":"Negative","isCorrect":false},{"text":"Zero","isCorrect":true},{"text":"Depends on the radius","isCorrect":false}]'::jsonb,
 null, 'The centripetal force is always directed perpendicular to the particle''s velocity (and hence displacement), so it does no work on the particle.'),
('NEET UG', 'Physics', 'Mechanics', 'easy', 'mcq',
 'The escape velocity from the surface of the Earth is approximately:',
 '[{"text":"1.12 km/s","isCorrect":false},{"text":"11.2 km/s","isCorrect":true},{"text":"112 km/s","isCorrect":false},{"text":"0.112 km/s","isCorrect":false}]'::jsonb,
 null, 'The escape velocity from Earth''s surface, given by sqrt(2gR), is approximately 11.2 km/s.'),

-- Physics: Electrodynamics
('NEET UG', 'Physics', 'Electrodynamics', 'easy', 'mcq',
 'The SI unit of electrical resistance is the:',
 '[{"text":"Ohm","isCorrect":true},{"text":"Farad","isCorrect":false},{"text":"Henry","isCorrect":false},{"text":"Weber","isCorrect":false}]'::jsonb,
 null, 'Electrical resistance is measured in ohms, defined by Ohm''s law as V/I.'),
('NEET UG', 'Physics', 'Electrodynamics', 'medium', 'mcq',
 'In a purely resistive AC circuit, the voltage and current are:',
 '[{"text":"In phase with each other","isCorrect":true},{"text":"90 degrees out of phase","isCorrect":false},{"text":"180 degrees out of phase","isCorrect":false},{"text":"Always independent of each other","isCorrect":false}]'::jsonb,
 null, 'In a purely resistive AC circuit, voltage and current reach their maximum and zero values simultaneously, so they remain in phase.'),
('NEET UG', 'Physics', 'Electrodynamics', 'medium', 'mcq',
 'The magnetic field at the center of a circular current-carrying loop of radius R carrying current I is given by:',
 '[{"text":"mu0*I/(2R)","isCorrect":true},{"text":"mu0*I/(2*pi*R)","isCorrect":false},{"text":"mu0*I*R/2","isCorrect":false},{"text":"mu0*I^2/(2R)","isCorrect":false}]'::jsonb,
 null, 'The magnetic field at the center of a circular current loop is B = mu0*I/(2R), derived from the Biot-Savart law.'),
('NEET UG', 'Physics', 'Electrodynamics', 'medium', 'mcq',
 'Lenz''s law, which determines the direction of an induced current, is a direct consequence of which conservation principle?',
 '[{"text":"Conservation of charge","isCorrect":false},{"text":"Conservation of energy","isCorrect":true},{"text":"Conservation of momentum","isCorrect":false},{"text":"Conservation of angular momentum","isCorrect":false}]'::jsonb,
 null, 'Lenz''s law states the induced current opposes the change producing it; if it did not, energy could be created from nothing, so the law is a consequence of energy conservation.'),

-- Physics: Optics and Wave Phenomena
('NEET UG', 'Physics', 'Optics and Wave Phenomena', 'easy', 'mcq',
 'The splitting of white light into its component colors on passing through a prism is called:',
 '[{"text":"Dispersion","isCorrect":true},{"text":"Diffraction","isCorrect":false},{"text":"Polarization","isCorrect":false},{"text":"Interference","isCorrect":false}]'::jsonb,
 null, 'Dispersion is the separation of white light into its constituent wavelengths (colors) because the refractive index of a medium varies with wavelength.'),
('NEET UG', 'Physics', 'Optics and Wave Phenomena', 'medium', 'mcq',
 'In Young''s double slit experiment, the fringe width beta is given by:',
 '[{"text":"lambda*D/d","isCorrect":true},{"text":"lambda*d/D","isCorrect":false},{"text":"D*d/lambda","isCorrect":false},{"text":"lambda/(D*d)","isCorrect":false}]'::jsonb,
 null, 'Fringe width beta = lambda*D/d, where lambda is the wavelength, D is the slit-to-screen distance, and d is the slit separation.'),
('NEET UG', 'Physics', 'Optics and Wave Phenomena', 'easy', 'mcq',
 'The apparent change in frequency of a wave due to relative motion between the source and the observer is called the:',
 '[{"text":"Doppler effect","isCorrect":true},{"text":"Photoelectric effect","isCorrect":false},{"text":"Compton effect","isCorrect":false},{"text":"Zeeman effect","isCorrect":false}]'::jsonb,
 null, 'The Doppler effect describes the apparent shift in observed frequency caused by relative motion between a wave source and an observer.'),
('NEET UG', 'Physics', 'Optics and Wave Phenomena', 'medium', 'mcq',
 'Myopia (near-sightedness) is corrected using which type of lens?',
 '[{"text":"Convex (converging) lens","isCorrect":false},{"text":"Concave (diverging) lens","isCorrect":true},{"text":"Cylindrical lens","isCorrect":false},{"text":"Bifocal lens only","isCorrect":false}]'::jsonb,
 null, 'In myopia, the image forms in front of the retina; a concave (diverging) lens diverges incoming rays slightly before they enter the eye, pushing the focal point back onto the retina.'),

-- Physics: Modern Physics and Semiconductor Devices
('NEET UG', 'Physics', 'Modern Physics and Semiconductor Devices', 'medium', 'mcq',
 'The photoelectric effect was successfully explained by:',
 '[{"text":"Newton, using the corpuscular theory","isCorrect":false},{"text":"Einstein, using the photon concept","isCorrect":true},{"text":"Huygens, using the wave theory","isCorrect":false},{"text":"Maxwell, using electromagnetic theory","isCorrect":false}]'::jsonb,
 null, 'Einstein explained the photoelectric effect by proposing that light consists of discrete photons, each carrying energy hf, that can eject electrons on collision if their energy exceeds the work function.'),
('NEET UG', 'Physics', 'Modern Physics and Semiconductor Devices', 'medium', 'mcq',
 'In a p-type semiconductor, the majority charge carriers are:',
 '[{"text":"Electrons","isCorrect":false},{"text":"Holes","isCorrect":true},{"text":"Protons","isCorrect":false},{"text":"Photons","isCorrect":false}]'::jsonb,
 null, 'A p-type semiconductor is doped with trivalent impurities, creating an excess of holes, which act as the majority charge carriers.'),
('NEET UG', 'Physics', 'Modern Physics and Semiconductor Devices', 'easy', 'mcq',
 'An alpha particle is equivalent to the nucleus of which atom?',
 '[{"text":"Hydrogen","isCorrect":false},{"text":"Helium","isCorrect":true},{"text":"Lithium","isCorrect":false},{"text":"Carbon","isCorrect":false}]'::jsonb,
 null, 'An alpha particle consists of 2 protons and 2 neutrons, identical to the nucleus of a helium atom.'),
('NEET UG', 'Physics', 'Modern Physics and Semiconductor Devices', 'medium', 'mcq',
 'Which semiconductor device is typically used as a voltage regulator, operating in reverse breakdown?',
 '[{"text":"Zener diode","isCorrect":true},{"text":"Photodiode","isCorrect":false},{"text":"Light-emitting diode","isCorrect":false},{"text":"Solar cell","isCorrect":false}]'::jsonb,
 null, 'A Zener diode is specifically designed to operate in reverse breakdown at a stable voltage, making it useful as a voltage regulator.'),

-- Chemistry: Physical Chemistry
('NEET UG', 'Chemistry', 'Physical Chemistry', 'easy', 'mcq',
 'The pH of a neutral aqueous solution at 25 degrees C is:',
 '[{"text":"0","isCorrect":false},{"text":"7","isCorrect":true},{"text":"14","isCorrect":false},{"text":"1","isCorrect":false}]'::jsonb,
 null, 'At 25 degrees C, pure water has equal concentrations of H+ and OH- ions, giving a pH of 7, which defines neutrality.'),
('NEET UG', 'Chemistry', 'Physical Chemistry', 'medium', 'mcq',
 'The SI-derived unit commonly used for molar conductivity is:',
 '[{"text":"S cm^2 mol^-1","isCorrect":true},{"text":"S cm^-1","isCorrect":false},{"text":"S mol^-1","isCorrect":false},{"text":"ohm cm mol^-1","isCorrect":false}]'::jsonb,
 null, 'Molar conductivity, defined as conductivity divided by molar concentration, is conventionally expressed in S cm^2 mol^-1.'),
('NEET UG', 'Chemistry', 'Physical Chemistry', 'medium', 'mcq',
 'The law stating that the rate of a reaction is proportional to the product of the concentrations of reactants, each raised to an appropriate power, is called the:',
 '[{"text":"Law of mass action","isCorrect":true},{"text":"Law of conservation of mass","isCorrect":false},{"text":"Law of multiple proportions","isCorrect":false},{"text":"Raoult''s law","isCorrect":false}]'::jsonb,
 null, 'The law of mass action states that reaction rate is proportional to the product of the active masses (concentrations) of the reactants raised to powers matching their stoichiometric coefficients (for elementary reactions).'),
('NEET UG', 'Chemistry', 'Physical Chemistry', 'easy', 'mcq',
 'The number of moles of solute dissolved per liter of solution is called:',
 '[{"text":"Molarity","isCorrect":true},{"text":"Molality","isCorrect":false},{"text":"Normality only","isCorrect":false},{"text":"Mole fraction","isCorrect":false}]'::jsonb,
 null, 'Molarity is defined as moles of solute per liter of solution, distinct from molality, which uses mass of solvent instead of solution volume.'),

-- Chemistry: Organic Chemistry
('NEET UG', 'Chemistry', 'Organic Chemistry', 'easy', 'mcq',
 'The functional group -COOH represents which class of organic compounds?',
 '[{"text":"Carboxylic acids","isCorrect":true},{"text":"Aldehydes","isCorrect":false},{"text":"Ketones","isCorrect":false},{"text":"Esters","isCorrect":false}]'::jsonb,
 null, 'The -COOH group defines the carboxylic acid functional class, combining a carbonyl and hydroxyl group on the same carbon.'),
('NEET UG', 'Chemistry', 'Organic Chemistry', 'medium', 'mcq',
 'Markovnikov''s rule is applied to predict the product of which type of reaction?',
 '[{"text":"Addition of HX to an unsymmetrical alkene","isCorrect":true},{"text":"Esterification of a carboxylic acid","isCorrect":false},{"text":"Nucleophilic substitution on an alkyl halide","isCorrect":false},{"text":"Oxidation of a primary alcohol","isCorrect":false}]'::jsonb,
 null, 'Markovnikov''s rule predicts that in the addition of HX to an unsymmetrical alkene, the H atom attaches to the carbon with more hydrogens already, and X attaches to the more substituted carbon (via the more stable carbocation intermediate).'),
('NEET UG', 'Chemistry', 'Organic Chemistry', 'hard', 'mcq',
 'Which reagent is commonly used to distinguish between primary, secondary, and tertiary alcohols based on differing reaction rates?',
 '[{"text":"Lucas reagent","isCorrect":true},{"text":"Tollens'' reagent","isCorrect":false},{"text":"Fehling''s solution","isCorrect":false},{"text":"Grignard reagent","isCorrect":false}]'::jsonb,
 null, 'Lucas reagent (concentrated HCl with anhydrous ZnCl2) distinguishes alcohols by the differing rates at which they form an insoluble alkyl chloride -- tertiary alcohols react immediately, secondary within minutes, and primary alcohols very slowly.'),
('NEET UG', 'Chemistry', 'Organic Chemistry', 'medium', 'mcq',
 'The IUPAC name of the compound commonly known as acetone is:',
 '[{"text":"Propan-2-one","isCorrect":true},{"text":"Propan-1-ol","isCorrect":false},{"text":"Methyl formate","isCorrect":false},{"text":"Ethanal","isCorrect":false}]'::jsonb,
 null, 'Acetone, CH3-CO-CH3, is systematically named propan-2-one (propanone) under IUPAC nomenclature.'),

