-- Botany: Plant Physiology
('NEET UG', 'Botany', 'Plant Physiology', 'easy', 'mcq',
 'Photosynthesis occurs in which cell organelle?',
 '[{"text":"Mitochondria","isCorrect":false},{"text":"Chloroplast","isCorrect":true},{"text":"Golgi apparatus","isCorrect":false},{"text":"Ribosome","isCorrect":false}]'::jsonb,
 null, 'Chloroplasts contain chlorophyll and the enzymatic machinery needed to carry out both the light and dark reactions of photosynthesis.'),
('NEET UG', 'Botany', 'Plant Physiology', 'medium', 'mcq',
